module uart_tx #(parameter CLKS_PER_BIT=16)(input wire clk,rst_n,start,input wire [7:0] data,output reg tx,output reg busy,done); localparam IDLE=0,START=1,DATA=2,STOP=3; reg [1:0] state; reg [$clog2(CLKS_PER_BIT)-1:0] clk_count; reg [2:0] bit_index; reg [7:0] data_reg; always @(posedge clk or negedge rst_n) begin if(!rst_n) begin state<=IDLE;tx<=1;busy<=0;done<=0;clk_count<=0;bit_index<=0;data_reg<=0;end else begin done<=0; case(state) IDLE:begin tx<=1;busy<=0;clk_count<=0;if(start)begin data_reg<=data;state<=START;busy<=1;tx<=0;end end START:if(clk_count==CLKS_PER_BIT-1)begin clk_count<=0;bit_index<=0;state<=DATA;tx<=data_reg[0];end else clk_count<=clk_count+1'b1; DATA:if(clk_count==CLKS_PER_BIT-1)begin clk_count<=0;if(bit_index==7)begin state<=STOP;tx<=1;end else begin bit_index<=bit_index+1'b1;data_reg<=data_reg>>1;tx<=data_reg[1];end end else clk_count<=clk_count+1'b1; STOP:if(clk_count==CLKS_PER_BIT-1)begin clk_count<=0;state<=IDLE;busy<=0;done<=1;tx<=1;end else clk_count<=clk_count+1'b1; default:state<=IDLE; endcase end end endmodule
